payload.query:
subscription ShotFeedSubscribeToGolfTournamentTeamsShotFeed(
  $input: SubscribeToGolfTournamentTeamsShotFeedInput!
) {
  subscribeToGolfTournamentTeamsShotFeed(input: $input) {
    ...ShotFeedGolfTournamentTeamsShotFeedFields
  }
}

fragment ShotFeedGolfTournamentTeamsShotFeedFields on GolfTournamentShotFeedEvent {
  id
  teamId
  shotNo
  eventType
  isProvisional
  provisionalIndex
  holeScore
  surfaceTypeCode
  prevSurfaceTypeCode
  shotDistance
  distanceToPin
}
